import { Outfit, Noto_Sans_KR } from "next/font/google";

/**
 * AURORA PAINT 오로라 페인트 — a fictional paint studio whose medium is light.
 * The voice is luminous and airy. Outfit — a clean geometric sans with a soft
 * even color that lets the flowing aurora gradient do the talking on the
 * wordmark. Noto Sans KR (300/500) — the calm Hangul weight for the bilingual
 * copy.
 *
 * styles.css consumes these as var(--font-outfit) / var(--font-noto-sans-kr);
 * page.tsx applies the .variable classes on the entry root.
 */
export const outfit = Outfit({
  weight: ["300", "400", "600", "800"],
  subsets: ["latin"],
  variable: "--font-outfit",
  display: "swap",
});

export const notoSansKR = Noto_Sans_KR({
  weight: ["300", "400", "500", "700"],
  subsets: ["latin"],
  variable: "--font-noto-sans-kr",
  display: "swap",
});

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { outfit, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "AURORA PAINT";

/** Ribbon hues (mint / violet / cyan / spring) for the additive aurora. */
const RIBBONS = [
  { hue: 158, sat: 92, light: 70 }, // mint
  { hue: 270, sat: 88, light: 72 }, // violet
  { hue: 188, sat: 95, light: 66 }, // cyan
  { hue: 140, sat: 90, light: 74 }, // spring green
];

/**
 * AURORA PAINT 오로라 페인트 — a paint studio whose medium is light. The
 * signature is a canvas aurora: several sine-driven ribbons of additive
 * light (mint / violet / cyan) flow across the canvas using `lighter`
 * compositing so they bloom where they overlap. The pointer adds a brush
 * stroke of light that trails the cursor. Under reduced motion the canvas
 * is composed once at a chosen phase and frozen — a still of light.
 *
 * The wordmark "AURORA PAINT" carries the same spectrum as a clipped text
 * gradient with a soft glow. `.aurora-paint-js` is added on mount so the
 * no-JS markup is the finished page.
 */
export default function AuroraPaintPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const stageRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("aurora-paint-js");
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "aurora-paint" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  // Canvas aurora — additive light ribbons + a pointer brush.
  useEffect(() => {
    const canvas = canvasRef.current;
    const stage = stageRef.current;
    if (!canvas || !stage) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const MAX_DPR = 2;
    const EPS = 1;
    let w = 0;
    let h = 0;
    const brush = { x: 0, y: 0, tx: 0, ty: 0, life: 0 }; // pointer trail

    const resize = () => {
      const rect = stage.getBoundingClientRect();
      const ww = Math.max(EPS, rect.width);
      const hh = Math.max(EPS, rect.height);
      const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
      canvas.width = Math.max(1, Math.round(ww * dpr));
      canvas.height = Math.max(1, Math.round(hh * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      w = ww;
      h = hh;
    };

    // Each ribbon: a vertical band swept by a sine, amplitude / speed / phase.
    const ribbons = RIBBONS.map((r, i) => ({
      ...r,
      band: 0.2 + i * 0.18, // vertical center 0..1
      amp: 0.12 + i * 0.05,
      speed: 0.0006 + i * 0.00018,
      phase: i * 1.7,
      thick: 90 + i * 26,
    }));

    let raf = 0;
    let t0 = performance.now();
    let running = false;
    let visible = false;

    const draw = (now: number) => {
      const t = now - t0;
      // Low-alpha clear leaves a soft trail so the light blooms.
      ctx.globalCompositeOperation = "source-over";
      ctx.fillStyle = "rgba(6, 10, 16, 0.16)";
      ctx.fillRect(0, 0, w, h);

      // Additive light — where ribbons overlap they brighten.
      ctx.globalCompositeOperation = "lighter";
      for (const rb of ribbons) {
        const yc = rb.band * h;
        const amp = rb.amp * h;
        ctx.beginPath();
        for (let x = -20; x <= w + 20; x += 8) {
          const nx = x / Math.max(EPS, w);
          const y =
            yc +
            Math.sin(nx * Math.PI * 2.4 + t * rb.speed * 1000 + rb.phase) * amp +
            Math.sin(nx * Math.PI * 5.1 + t * rb.speed * 600) * amp * 0.32;
          if (!Number.isFinite(y)) continue;
          if (x === -20) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        const grad = ctx.createLinearGradient(0, yc - amp, 0, yc + amp);
        const lw = Math.max(EPS, rb.thick);
        grad.addColorStop(0, `hsla(${rb.hue}, ${rb.sat}%, ${rb.light}%, 0)`);
        grad.addColorStop(0.5, `hsla(${rb.hue}, ${rb.sat}%, ${rb.light}%, 0.5)`);
        grad.addColorStop(1, `hsla(${rb.hue}, ${rb.sat}%, ${rb.light}%, 0)`);
        ctx.strokeStyle = grad;
        ctx.lineWidth = lw;
        ctx.lineCap = "round";
        ctx.shadowBlur = 40;
        ctx.shadowColor = `hsla(${rb.hue}, ${rb.sat}%, ${rb.light}%, 0.7)`;
        ctx.stroke();
      }
      ctx.shadowBlur = 0;

      // Pointer brush stroke of light — trails the cursor with inertia.
      brush.x += (brush.tx - brush.x) * 0.18;
      brush.y += (brush.ty - brush.y) * 0.18;
      brush.life = Math.max(0, brush.life - 0.02);
      if (brush.life > 0 && Number.isFinite(brush.x) && Number.isFinite(brush.y)) {
        const rad = Math.max(EPS, 120 * brush.life);
        const g = ctx.createRadialGradient(brush.x, brush.y, 0, brush.x, brush.y, rad);
        g.addColorStop(0, "hsla(160, 95%, 78%, 0.55)");
        g.addColorStop(0.5, "hsla(190, 90%, 70%, 0.22)");
        g.addColorStop(1, "hsla(270, 80%, 72%, 0)");
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(brush.x, brush.y, rad, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalCompositeOperation = "source-over";
    };

    const frame = (now: number) => {
      raf = requestAnimationFrame(frame);
      draw(now);
    };
    const start = () => {
      if (running) return;
      running = true;
      t0 = performance.now();
      raf = requestAnimationFrame(frame);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const compose = () => {
      // Reduced-motion still: paint a few frames at a fixed phase, then freeze.
      resize();
      for (let k = 0; k < 28; k++) draw(t0 + k * 32);
    };

    resize();
    if (reduced) compose();
    else start();

    const ro = new ResizeObserver(() => {
      resize();
      if (reduced) compose();
    });
    ro.observe(stage);
    const io = new IntersectionObserver(
      (hits) => {
        visible = hits[hits.length - 1].isIntersecting;
        if (visible && !document.hidden && !reduced) start();
        else stop();
      },
      { rootMargin: "80px 0px" },
    );
    io.observe(stage);
    const onVis = () => {
      if (document.hidden) stop();
      else if (visible && !reduced) start();
    };
    document.addEventListener("visibilitychange", onVis);

    const onMove = (ev: PointerEvent) => {
      if (reduced) return;
      const rect = stage.getBoundingClientRect();
      if (rect.width < EPS) return;
      const nx = ev.clientX - rect.left;
      const ny = ev.clientY - rect.top;
      if (Number.isFinite(nx) && Number.isFinite(ny)) {
        brush.tx = nx;
        brush.ty = ny;
        brush.life = 1;
      }
    };
    window.addEventListener("pointermove", onMove, { passive: true });

    return () => {
      stop();
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      window.removeEventListener("pointermove", onMove);
    };
  }, [reduced]);

  return (
    <div ref={rootRef} className={`${outfit.variable} ${notoSansKR.variable} aurora-paint-root`}>
      <div ref={stageRef} className="aurora-paint-stage" aria-hidden="true">
        <canvas ref={canvasRef} className="aurora-paint-canvas" />
      </div>
      <div ref={revealRef} className="aurora-paint-doc">
        <header className="aurora-paint-hero">
          <p className="aurora-paint-kicker">
            <span lang="ko">오로라 페인트</span> · A STUDIO OF LIGHT · 2026
          </p>
          <h1 className="aurora-paint-title" aria-label={TITLE}>
            <span className="aurora-paint-foil" aria-hidden="true">
              {TITLE.split("").map((ch, i) => (
                <span key={i} className="aurora-paint-glyph" style={{ "--ap-i": i } as CSSProperties}>
                  {ch === " " ? "\u00A0" : ch}
                </span>
              ))}
            </span>
          </h1>
          <p className="aurora-paint-title__ko" lang="ko">오로라 페인트</p>
          <p className="aurora-paint-sub">
            <span lang="ko">빛을 칠하다.</span> Paint made of light.
          </p>
          <p className="aurora-paint-hint" lang="ko">움직여 보세요 — 빛이 당신을 따라 칠해집니다.</p>
        </header>

        <main>
          <section className="aurora-paint-grid">
            {[
              { ko: "민트 글로우", en: "Mint glow", n: "01" },
              { ko: "바이올렛 리본", en: "Violet ribbon", n: "02" },
              { ko: "시안 브러시", en: "Cyan brush", n: "03" },
            ].map((c, i) => (
              <article
                key={i}
                className="aurora-paint-card"
                data-reveal
                style={{ "--ap-d": i * 90 } as CSSProperties}
              >
                <span className="aurora-paint-card__n">{c.n}</span>
                <span className="aurora-paint-card__en">{c.en}</span>
                <span className="aurora-paint-card__ko" lang="ko">{c.ko}</span>
              </article>
            ))}
          </section>

          <section className="aurora-paint-lead" data-reveal>
            <p className="aurora-paint-lead__p">
              <span lang="ko">
                우리는 페인트를 팔지 않는다. 빛을 칠한다. 가산 혼합으로 —
                겹치는 곳마다 밝아지고, 흐르는 곳마다 색이 된다.
              </span>{" "}
              We don't sell paint. We paint light. By the law of addition —
              where the ribbons overlap it brightens, where they flow it becomes
              color.
            </p>
          </section>
        </main>

        <footer className="aurora-paint-foot">
          <span>AURORA PAINT · 2026</span>
          <span lang="ko">오로라 페인트 — 서울</span>
        </footer>
      </div>
    </div>
  );
}

.aurora-paint-root {
  --ap-bg: #06090f;
  --ap-deep: #04060a;
  --ap-text: #eaf6ff;
  --ap-mute: #8aa6b8;
  --ap-mint: #7ef9c4;
  --ap-violet: #b388ff;
  --ap-cyan: #5ee0ff;
  --ap-font-display: var(--font-outfit), "Outfit", system-ui, sans-serif;
  --ap-font-kr: var(--font-noto-sans-kr), "Noto Sans KR", sans-serif;
  --ap-ease: cubic-bezier(0.16, 1, 0.3, 1);

  position: relative;
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(60% 50% at 50% 0%, rgba(126, 249, 196, 0.08), transparent 70%),
    radial-gradient(40% 40% at 90% 90%, rgba(179, 136, 255, 0.07), transparent 70%),
    var(--ap-bg);
  color: var(--ap-text);
  font-family: var(--ap-font-kr);
  font-weight: 300;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}
.aurora-paint-root ::selection { background: var(--ap-mint); color: var(--ap-deep); }

/* ---- Canvas stage (the aurora) ---- */
.aurora-paint-stage {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}
/* No-JS understudy: a static radial aurora gradient so the canvas's absence
   still reads as light, never a flat void. */
.aurora-paint-canvas {
  display: block;
  width: 100%;
  height: 100%;
  background:
    radial-gradient(50% 60% at 30% 40%, rgba(126, 249, 196, 0.28), transparent 70%),
    radial-gradient(46% 54% at 70% 30%, rgba(179, 136, 255, 0.24), transparent 72%),
    radial-gradient(54% 60% at 50% 80%, rgba(94, 224, 255, 0.22), transparent 72%),
    var(--ap-bg);
}

.aurora-paint-doc {
  position: relative;
  z-index: 1;
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}

/* ---- Hero ---- */
.aurora-paint-hero {
  min-height: 86vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(3rem, 10vh, 7rem) 0 2rem;
}
.aurora-paint-kicker {
  margin: 0 0 1.4rem;
  font-family: var(--ap-font-display);
  font-size: clamp(0.72rem, 1.1vw, 0.86rem);
  font-weight: 400;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: var(--ap-mint);
}
.aurora-paint-title {
  margin: 0;
  font-family: var(--ap-font-display);
  font-weight: 800;
  font-size: clamp(2.4rem, 10vw, 8rem);
  line-height: 0.92;
  letter-spacing: -0.02em;
}
/* The aurora foil: a flowing mint→violet→cyan gradient clipped to the glyphs,
   with a soft outer glow — the wordmark IS the ribbons of light. */
.aurora-paint-foil {
  display: inline-block;
  background: linear-gradient(100deg, #7ef9c4 0%, #b388ff 45%, #5ee0ff 75%, #7ef9c4 100%);
  background-size: 220% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
  filter:
    drop-shadow(0 0 24px rgba(126, 249, 196, 0.45))
    drop-shadow(0 0 48px rgba(179, 136, 255, 0.35));
  animation: ap-flow 9s linear infinite;
}
@keyframes ap-flow {
  to { background-position: 220% 0; }
}
@media (prefers-reduced-motion: reduce) { .aurora-paint-foil { animation: none; } }
.aurora-paint-glyph { display: inline-block; }
.aurora-paint-title__ko {
  margin: 0.6rem 0 0;
  font-family: var(--ap-font-kr);
  font-weight: 300;
  font-size: clamp(1rem, 2.4vw, 1.6rem);
  letter-spacing: 0.42em;
  color: var(--ap-mute);
}
.aurora-paint-sub {
  margin: 1.6rem 0 0.4rem;
  font-size: clamp(1.05rem, 1.9vw, 1.4rem);
  font-weight: 400;
}
.aurora-paint-sub span[lang="ko"] { color: var(--ap-mute); margin-right: 0.5rem; }
.aurora-paint-hint {
  margin: 0;
  font-size: 0.86rem;
  color: var(--ap-cyan);
  opacity: 0.85;
}

/* ---- Grid cards ---- */
.aurora-paint-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: clamp(0.9rem, 1.6vw, 1.3rem);
  padding: clamp(1rem, 3vw, 2rem) 0;
}
.aurora-paint-card {
  position: relative;
  padding: clamp(1.2rem, 2.4vw, 1.8rem);
  border-radius: 18px;
  min-height: 160px;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  justify-content: flex-end;
  background:
    linear-gradient(135deg, rgba(126, 249, 196, 0.14), rgba(94, 224, 255, 0.12)),
    rgba(10, 16, 26, 0.5);
  border: 1px solid rgba(126, 249, 196, 0.22);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12), 0 24px 48px -28px rgba(2, 6, 12, 0.9);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  overflow: hidden;
}
.aurora-paint-card__n { font-family: var(--ap-font-display); font-weight: 800; font-size: 0.8rem; color: var(--ap-mint); letter-spacing: 0.2em; }
.aurora-paint-card__en { font-family: var(--ap-font-display); font-weight: 600; font-size: 1.2rem; }
.aurora-paint-card__ko { font-size: 0.9rem; color: var(--ap-mute); }

.aurora-paint-lead {
  padding: clamp(2.5rem, 6vw, 4rem) 0;
  border-top: 1px solid rgba(126, 249, 196, 0.16);
}
.aurora-paint-lead__p {
  margin: 0 auto;
  max-width: 62ch;
  font-family: var(--ap-font-display);
  font-weight: 300;
  font-size: clamp(1.15rem, 2.4vw, 1.7rem);
  line-height: 1.5;
  text-align: center;
}
.aurora-paint-lead__p span[lang="ko"] {
  display: block;
  font-family: var(--ap-font-kr);
  color: var(--ap-mute);
  font-size: 0.74em;
  margin-bottom: 0.6em;
}

.aurora-paint-foot {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: clamp(2rem, 5vw, 3rem) 0;
  border-top: 1px solid rgba(126, 249, 196, 0.16);
  font-size: 0.8rem;
  letter-spacing: 0.06em;
  color: var(--ap-mute);
  font-family: var(--ap-font-display);
}

/* ---- Reveal gating ---- */
.aurora-paint-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--ap-ease), transform 800ms var(--ap-ease);
  transition-delay: calc(var(--ap-d, 0) * 1ms);
}
.aurora-paint-js [data-reveal].is-visible { opacity: 1; transform: none; }
.aurora-paint-js .aurora-paint-glyph {
  opacity: 0;
  transform: translateY(0.35em);
  display: inline-block;
  transition: opacity 700ms var(--ap-ease), transform 700ms var(--ap-ease);
  transition-delay: calc(var(--ap-i) * 70ms + 150ms);
}
.aurora-paint-js.is-mounted .aurora-paint-glyph { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  .aurora-paint-js [data-reveal], .aurora-paint-js .aurora-paint-glyph {
    opacity: 1 !important; transform: none !important; transition: none !important;
  }
}
.aurora-paint-root :focus-visible { outline: 2px solid var(--ap-mint); outline-offset: 3px; }
